#pragma once

// 编辑此文件以获得更多性能，并自定义支持的特性

///////////////////////////////////////////////////////////////////////////////
// 在 Linux 下，可以使用更快的 CLOCK_REALTIME_COARSE 时钟。
// 这个时钟不太精确，可能会有几十毫秒的误差，这取决于 the kernel HZ。
// 取消注释，使用它代替常规时钟。
//
// #define SPDLOG_CLOCK_COARSE
///////////////////////////////////////////////////////////////////////////////

///////////////////////////////////////////////////////////////////////////////
// 如果日期/时间日志不需要，并且永远不会出现在日志模式中，取消注释。
// 这将防止 spdlog 查询每个日志调用的时钟。
//
// 警告：如果日志模式包含任何日期/时间，而该标志处于开启状态，则结果是未定义的。
//          必须设置 new pattern(spdlog::set_pattern(..") 不包含日期/时间
//
// #define SPDLOG_NO_DATETIME
///////////////////////////////////////////////////////////////////////////////

///////////////////////////////////////////////////////////////////////////////
// 如果不需要线程 id 日志记录，取消注释（即日志模式中没有%t）。
// 这将防止 spdlog 查询每个日志调用的线程 id。
//
// 警告：如果日志模式包含线程 id（即%t），而此标志处于开启状态，则结果未定义。
//
// #define SPDLOG_NO_THREAD_ID
///////////////////////////////////////////////////////////////////////////////

///////////////////////////////////////////////////////////////////////////////
// 取消注释以防止 spdlog 在线程本地存储中缓存线程 id。
// 默认情况下，spdlog 在 tls 中保存线程 id，为每个调用获得几个毫秒。
//
// 警告：如果你的程序 forks，取消注释此标志以防止在子线程日志中出现未定义的线程id。
//
// #define SPDLOG_DISABLE_TID_CACHING
///////////////////////////////////////////////////////////////////////////////

///////////////////////////////////////////////////////////////////////////////
// 如果不需要记录器名称日志记录，取消注释。
// 这将防止 spdlog 在每次日志调用时复制日志记录器的名称。
//
// #define SPDLOG_NO_NAME
///////////////////////////////////////////////////////////////////////////////

///////////////////////////////////////////////////////////////////////////////
// 取消注释以启用 SPDLOG_DEBUG/SPDLOG_TRACE 宏。
//
// #define SPDLOG_DEBUG_ON
// #define SPDLOG_TRACE_ON
///////////////////////////////////////////////////////////////////////////////

///////////////////////////////////////////////////////////////////////////////
// 取消注释以避免锁定注册表操作 (spdlog::get(), spdlog::drop（) spdlog::register()）。
// 如果你的代码从来都不同时修改注册表，才可以使用。（一般还是关着吧）
// 注意，在创建一个日志程序（logger）后，注册表就会被 spdlog 修改
//
// #define SPDLOG_NO_REGISTRY_MUTEX
///////////////////////////////////////////////////////////////////////////////

///////////////////////////////////////////////////////////////////////////////
// 取消注释以避免spdlog使用原子日志级别（atomic log levels）
// 只有当你的代码从不通过不同的线程并发地修改日志记录器的日志级别时才使用。（一般还是关着吧）
//
// #define SPDLOG_NO_ATOMIC_LEVELS
///////////////////////////////////////////////////////////////////////////////

///////////////////////////////////////////////////////////////////////////////
// 取消注释，在 Windows 上启用 wchar_t 文件名。
//
// #define SPDLOG_WCHAR_FILENAMES
///////////////////////////////////////////////////////////////////////////////

///////////////////////////////////////////////////////////////////////////////
// 取消注释以启用 wchar_t 支持 (convert to utf8)
//
// #define SPDLOG_WCHAR_TO_UTF8_SUPPORT
///////////////////////////////////////////////////////////////////////////////

///////////////////////////////////////////////////////////////////////////////
// 取消注释以覆盖默认 eol （“\n”或“\r\n”在Linux/Windows下）
// 这将把 SPDLOG_EOL 定义为 ";-)\n"，即每行结束时会输出 ";-)"，然后换行。
// 在你的代码中，任何使用 SPDLOG_EOL 的地方都会使用这个新的行结束符。
//
// #define SPDLOG_EOL ";-)\n"
///////////////////////////////////////////////////////////////////////////////

///////////////////////////////////////////////////////////////////////////////
// 取消注释，使用您自己的 fmt 库副本，而不是 spdlog 的副本。
// 在这种情况下，spdlog 将尝试包含 <fmt/format.h>，因此设置相应的 -I 标志。
// fmt 是一个开源的 C++ 格式化库，提供了类似 Python 的 str.format() 功能，用于安全、高效地格式化字符串。它是由 Victor Zverovich 开发的，并且在 C++ 社区中广泛使用，尤其是在需要复杂字符串格式化的场景中。
// -I 标志用于指定编译器搜索头文件的目录。当你使用第三方库（如 fmt）时，库的头文件通常不在标准的系统头文件目录中，因此需要通过 -I 标志告诉编译器去哪里查找这些头文件。
// 
// #define SPDLOG_FMT_EXTERNAL
///////////////////////////////////////////////////////////////////////////////

///////////////////////////////////////////////////////////////////////////////
// 取消注释，在日志中使用 printf-style 的消息，来代替默认的 format-style
//
// #define SPDLOG_FMT_PRINTF
///////////////////////////////////////////////////////////////////////////////

///////////////////////////////////////////////////////////////////////////////
// 取消注释，启用 syslog（默认禁用）
// syslog 是一种用于系统级日志记录的协议和工具，广泛用于 Unix 和 Linux 系统。它主要用于记录操作系统和系统服务的日志信息。
// spdlog 是一个高性能的 C++ 日志库，适用于应用程序级别的日志记录。它提供了简单易用的接口和丰富的功能，适合现代 C++ 应用程序。
//
// #define SPDLOG_ENABLE_SYSLOG
///////////////////////////////////////////////////////////////////////////////

///////////////////////////////////////////////////////////////////////////////
// 取消注释以防止子进程继承日志文件描述符
//
// #define SPDLOG_PREVENT_CHILD_FD
///////////////////////////////////////////////////////////////////////////////

///////////////////////////////////////////////////////////////////////////////
// 如果编译器不支持 “ final ” 关键字，取消注释。final 关键字：用于防止类被继承或防止虚函数被重写。
// final 关键字允许在发布中进行更多优化。使用 final 可以帮助编译器进行优化，因为它明确了继承关系。
// 使用最新的编译器。请参阅 GCC 的文档了解 -Wsuggest-final-types
//
// #define SPDLOG_NO_FINAL
///////////////////////////////////////////////////////////////////////////////

///////////////////////////////////////////////////////////////////////////////
// 取消注释以启用消息计数功能。
// 使用 logger pattern 中的 %i 来显示日志消息序列 id。
//
// #define SPDLOG_ENABLE_MESSAGE_COUNTER
///////////////////////////////////////////////////////////////////////////////

///////////////////////////////////////////////////////////////////////////////
// 取消注释以自定义 level 名称(e.g. "MT TRACE")
//
// #define SPDLOG_LEVEL_NAMES { "MY TRACE", "MY DEBUG", "MY INFO", "MY WARNING", "MY ERROR", "MY CRITICAL", "OFF" }
